const out={asOf:new Date().toISOString().slice(0,16)+'Z',errors:[],services:[],transit:[]};const J=async u=>{const r=await fetch(u);if(!r.ok)throw new Error('HTTP '+r.status);return r.json()};const cl=s=>(s||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
const SP=[['GitHub','https://www.githubstatus.com'],['Cloudflare','https://www.cloudflarestatus.com'],['Discord','https://discordstatus.com'],['Dropbox','https://status.dropbox.com'],['OpenAI','https://status.openai.com'],['Reddit','https://www.redditstatus.com'],['Atlassian','https://status.atlassian.com'],['Twilio','https://status.twilio.com'],['DigitalOcean','https://status.digitalocean.com'],['Vercel','https://www.vercel-status.com'],['Coinbase','https://status.coinbase.com'],['Squarespace','https://status.squarespace.com'],['Shopify','https://www.shopifystatus.com'],['Linear','https://linearstatus.com'],['Trello','https://trello.status.atlassian.com'],['Epic Games','https://status.epicgames.com']];
for(const [name,base] of SP){try{const d=await J(base+'/api/v2/summary.json');const inc=(d.incidents||[]).filter(i=>i.status!=='resolved'&&i.status!=='postmortem').map(i=>[i.name,i.impact,i.status,i.shortlink||base,cl(i.incident_updates?.[0]?.body||'').slice(0,240),i.created_at]);const comps=(d.components||[]).filter(c=>c.status&&c.status!=='operational'&&!c.group).map(c=>[c.name,c.status]).slice(0,8);out.services.push([name,d.status?.indicator||'none',d.status?.description||'',inc,comps,base,'statuspage'])}catch(e){out.errors.push(name+' '+e.message)}}
try{const d=await J('https://slack-status.com/api/v2.0.0/current');out.services.push(['Slack',d.status==='ok'?'none':'major',d.status==='ok'?'All Systems Operational':'Active incidents',(d.active_incidents||[]).map(i=>[i.title,i.type,i.status,i.url,cl(i.notes?.[0]?.body||'').slice(0,240),i.date_created]),[],'https://slack-status.com','slack'])}catch(e){out.errors.push('Slack '+e.message)}
try{const d=await J('https://status.cloud.google.com/incidents.json');const open=d.filter(i=>!i.end).map(i=>[cl(i.external_desc).slice(0,140),i.severity||'',i.status_impact||'',i.uri?'https://status.cloud.google.com'+i.uri:'https://status.cloud.google.com',cl(i.most_recent_update?.text||'').slice(0,240),i.begin]);out.services.push(['Google Cloud',open.length?(open.some(i=>/high|SERVICE_OUTAGE/i.test(i[1]+i[2]))?'major':'minor'):'none',open.length?open.length+' open incident(s)':'No open incidents',open,[],'https://status.cloud.google.com','gcp'])}catch(e){out.errors.push('GCP '+e.message)}
try{const t=await (await fetch('https://xnotify.xboxlive.com/servicestatusv6/US/en-US')).text();const x=new DOMParser().parseFromString(t,'text/xml');const bad=[...x.querySelectorAll('Service')].map(s=>[s.querySelector('Name')?.textContent||'',s.querySelector('Status')?.textContent||'']).filter(s=>s[1]&&!/^(Up|Healthy|None)$/i.test(s[1]));out.services.push(['Xbox Live',bad.length?'minor':'none',bad.length?bad.length+' service(s) with issues':'All services up',[],bad.slice(0,8),'https://support.xbox.com/xbox-live-status','xbox'])}catch(e){out.errors.push('Xbox '+e.message)}
try{const d=await J('https://api-v3.mbta.com/alerts?filter[activity]=BOARD,EXIT,RIDE&page[limit]=60');const now=Date.now();const act=d.data.filter(a=>{const p=a.attributes.active_period||[];return p.some(x=>(!x.start||new Date(x.start)<=now)&&(!x.end||new Date(x.end)>=now))}).map(a=>[a.attributes.header.slice(0,160),a.attributes.effect,a.attributes.severity,a.attributes.updated_at]);out.transit.push(['MBTA (Boston)',act.length,act.filter(a=>a[2]>=7).slice(0,6),'https://www.mbta.com/alerts'])}catch(e){out.errors.push('MBTA '+e.message)}
try{const d=await J('https://api.bart.gov/api/bsa.aspx?cmd=bsa&key=MW9S-E7SL-26DU-VV8V&json=y');const b=d.root.bsa||[];const items=(Array.isArray(b)?b:[b]).map(x=>[cl(x.description?.['#cdata-section']||x.description||'').slice(0,160),x.type||'',x.station||'',x.posted||'']).filter(x=>!/No delays reported/i.test(x[0]));out.transit.push(['BART (San Francisco)',items.length,items.slice(0,6),'https://www.bart.gov/schedules/advisories'])}catch(e){out.errors.push('BART '+e.message)}
try{const d=await J('https://api-endpoint.mta.info/Dataservice/mtagtfsfeeds/camsys%2Fall-alerts.json');const now=Date.now()/1000;const ents=(d.entity||[]).filter(e=>e.alert&&(e.alert.active_period||[]).some(p=>(!p.start||p.start<=now)&&(!p.end||p.end>=now)));const sev=ents.map(e=>{const a=e.alert;const h=a.header_text?.translation?.find(t=>t.language==='en')?.text||'';const ag=[...new Set((a.informed_entity||[]).map(i=>i.agency_id).filter(Boolean))].join(',');return [h.slice(0,160),ag,a.effect||'',a['transit_realtime.mercury_alert']?.alert_type||'']});out.transit.push(['MTA (New York)',ents.length,sev.filter(s=>/Suspended|Delays|Service Change/i.test(s[3])).slice(0,8),'https://new.mta.info/alerts'])}catch(e){out.errors.push('MTA '+e.message)}
try{const since=new Date(Date.now()-7*864e5).toISOString().slice(0,19)+'.000';const until=new Date().toISOString().slice(0,19)+'.000';const d=await J(`https://services.nvd.nist.gov/rest/json/cves/2.0?resultsPerPage=1&pubStartDate=${since}&pubEndDate=${until}`);await new Promise(r=>setTimeout(r,6500));const c=await J(`https://services.nvd.nist.gov/rest/json/cves/2.0?resultsPerPage=1&pubStartDate=${since}&pubEndDate=${until}&cvssV3Severity=CRITICAL`);out.nvd={week:d.totalResults,critical:c.totalResults}}catch(e){out.errors.push('NVD '+e.message)}
try{const a=await J('https://api.weather.gov/alerts/active?status=actual&message_type=alert');const land=a.features.map(f=>f.properties).filter(p=>!/Gale|Small Craft|Marine|Hazardous Seas|Surf|Beach|Coastal Flood Advisory/.test(p.event));const ev={};land.forEach(p=>ev[p.event]=(ev[p.event]||0)+1);out.weather={total:a.features.length,land:land.length,extreme:land.filter(p=>p.severity==='Extreme').length,severe:land.filter(p=>p.severity==='Severe').length,byEvent:Object.entries(ev).sort((x,y)=>y[1]-x[1]).slice(0,8),top:land.filter(p=>/Extreme|Severe/.test(p.severity)).slice(0,6).map(p=>[p.event,p.areaDesc.slice(0,70),p.severity,p.ends||p.expires])}}catch(e){out.errors.push('NWS '+e.message)}

// Open Planet Observatory: "watch" collector, step A (CORS-friendly origin, e.g. https://api.weather.gov/).
// Output keys: asOf, hibp, wikiCE, shootings, shootMonths, nasa, nvdCrit, nobel, errors. All text is the source's own words.
const clean=s=>(s||'').replace(/\[[^\]]*\]/g,'').replace(/\s+/g,' ').trim();
const strip=s=>(s||'').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim();
const firstSentences=(t,n)=>{const p=(t||'').replace(/\s+/g,' ').replace(/\b(U\.S|U\.K|E\.U|Dr|Mr|Mrs|Ms|St|No|vs|etc|Inc|Ltd|Co|Jr|Sr|Prof|Gen|Sen|Rep|Gov|e\.g|i\.e|approx|Fig|al)\.(?=\s)/g,m=>m.replace(/\./g,'\u0001')).replace(/(\S)\.(?=\S)/g,'$1\u0001');const m=p.match(/[^.!?]+[.!?]+(\s|$)/g)||[p];return m.slice(0,n).join('').replace(/\u0001/g,'.').trim()};
const today=new Date();const iso=d=>d.toISOString().slice(0,10);
const out={asOf:today.toISOString().slice(0,16)+'Z',hibp:[],wikiCE:[],shootings:[],shootMonths:[],nasa:[],nvdCrit:{},nobel:[],errors:[]};
// 1. Have I Been Pwned: breaches added in the last 90 days (CC BY 4.0)
try{const b=await (await fetch('https://haveibeenpwned.com/api/v3/breaches')).json();const cut=iso(new Date(+today-90*864e5));
 out.hibp=b.filter(x=>(x.AddedDate||'').slice(0,10)>=cut).sort((a,b)=>a.AddedDate<b.AddedDate?1:-1).slice(0,60).map(x=>[x.Title,x.Domain,(x.BreachDate||'').slice(0,10),(x.AddedDate||'').slice(0,10),x.PwnCount,(x.DataClasses||[]).slice(0,8),firstSentences(strip(x.Description),2).slice(0,420),x.IsVerified?1:0,x.IsSensitive?1:0,x.LogoPath||'']);
 out.hibpTotal=b.length}catch(e){out.errors.push('hibp '+e.message)}
// 2. Wikipedia Portal:Current events, last 4 days, by section (CC BY-SA 4.0); each item keeps its own cited source link
try{const MON=['January','February','March','April','May','June','July','August','September','October','November','December'];
 for(let i=0;i<4;i++){const d=new Date(+today-i*864e5);const pg=`Portal:Current_events/${d.getUTCFullYear()}_${MON[d.getUTCMonth()]}_${d.getUTCDate()}`;
  const j=await (await fetch('https://en.wikipedia.org/w/api.php?action=parse&page='+encodeURIComponent(pg)+'&prop=text&format=json&formatversion=2&origin=*')).json();if(!j.parse)continue;
  const doc=new DOMParser().parseFromString(j.parse.text,'text/html');let sec='';
  const root=doc.querySelector('.current-events-content')||doc.body;
  const own=li=>{const c=li.cloneNode(true);c.querySelectorAll('ul').forEach(u=>u.remove());return c};
  const walk=(ul,chain)=>{for(const li of ul.querySelectorAll(':scope > li')){const sub=li.querySelector(':scope > ul');const c=own(li);const txt=clean(c.textContent);
    if(sub){walk(sub,[...chain,txt].slice(-2));continue}
    if(txt.length<20)continue;
    const ext=[...c.querySelectorAll('a.external')].map(a=>[clean(a.textContent).replace(/[()]/g,''),a.getAttribute('href')]).filter(x=>x[1]&&!x[1].includes('wikipedia.org')).slice(0,2);
    const wl=[...c.querySelectorAll('a[href^="/wiki/"]')].filter(a=>!/\/wiki\/[A-Za-z_]+:/.test(a.getAttribute('href'))).map(a=>a.getAttribute('title')||clean(a.textContent)).filter(Boolean).slice(0,6);
    out.wikiCE.push([iso(d),sec,chain.join(' › ').slice(0,140),txt.replace(/\s*\((?:[^()]|\([^()]*\))*\)\s*$/,'').slice(0,520),ext,wl,'https://en.wikipedia.org/wiki/'+pg]);}};
  for(const el of root.children){if(el.tagName==='P'){sec=clean(el.textContent);continue}if(el.tagName==='UL')walk(el,[])}}
 out.wikiCE=out.wikiCE.slice(0,220)}catch(e){out.errors.push('wikiCE '+e.message)}
// 3. Wikipedia: List of mass shootings in the United States in <year> (CC BY-SA 4.0); last 45 days + monthly tallies
try{const yr=today.getUTCFullYear();const h=await (await fetch(`https://en.wikipedia.org/api/rest_v1/page/html/List_of_mass_shootings_in_the_United_States_in_${yr}`)).text();
 const doc=new DOMParser().parseFromString(h,'text/html');const T=[...doc.querySelectorAll('table.wikitable')];
 const main=T.find(t=>/Description/.test(t.querySelector('tr')?.textContent||''));const months=T.find(t=>/^\s*Month/.test(t.querySelector('tr')?.textContent||''));
 const cut=new Date(+today-45*864e5);
 if(main){for(const r of [...main.querySelectorAll('tr')].slice(1)){const c=[...r.children];if(c.length<7)continue;const d=new Date(clean(c[0].textContent)+' '+yr+' UTC');if(isNaN(d)||d<cut)continue;
  let src=null;const sup=c[6].querySelector('sup a[href^="#cite"]');if(sup){const note=doc.querySelector(sup.getAttribute('href'));const a=note?.querySelector('a.external');if(a)src=[clean(a.textContent).slice(0,100),a.href]}
  out.shootings.push([iso(d),clean(c[1].textContent),clean(c[2].textContent),+clean(c[3].textContent)||0,+clean(c[4].textContent)||0,+clean(c[5].textContent)||0,clean(c[6].textContent).slice(0,480),src,`https://en.wikipedia.org/wiki/List_of_mass_shootings_in_the_United_States_in_${yr}`])}}
 if(months){for(const r of [...months.querySelectorAll('tr')].slice(1)){const c=[...r.children].map(x=>clean(x.textContent));if(c.length>=4&&!/Total/i.test(c[0]))out.shootMonths.push([c[0],+c[1]||0,+c[2]||0,+c[3]||0])}}
 out.shootDefs=T[0]?[...T[0].querySelectorAll('tr')].slice(1).map(r=>[...r.children].map(x=>clean(x.textContent).slice(0,200))):[]}catch(e){out.errors.push('shootings '+e.message)}
// 4. NASA news releases + NASA Science feed (US government work)
const rss=async(u,n,tag)=>{const t=await (await fetch(u)).text();const d=new DOMParser().parseFromString(t,'text/xml');return [...d.querySelectorAll('item')].slice(0,n).map(i=>[clean(i.querySelector('title')?.textContent),new Date(i.querySelector('pubDate')?.textContent||'').toISOString().slice(0,10),i.querySelector('link')?.textContent?.trim(),firstSentences(strip(i.querySelector('description')?.textContent),2).slice(0,300),tag])};
try{out.nasa=await rss('https://www.nasa.gov/news-release/feed/',15,'NASA news release')}catch(e){out.errors.push('nasa '+e.message)}
// 6. NVD: CRITICAL CVEs published in the last 7 days (public domain)
try{const s=new Date(+today-7*864e5).toISOString().slice(0,19)+'.000',e=today.toISOString().slice(0,19)+'.000';const j=await (await fetch(`https://services.nvd.nist.gov/rest/json/cves/2.0?pubStartDate=${s}&pubEndDate=${e}&cvssV3Severity=CRITICAL&resultsPerPage=40`)).json();
 out.nvdCrit={total:j.totalResults,items:(j.vulnerabilities||[]).map(v=>{const c=v.cve;const m=(c.metrics?.cvssMetricV31||c.metrics?.cvssMetricV30||[])[0]?.cvssData;return [c.id,(c.published||'').slice(0,10),m?.baseScore,firstSentences((c.descriptions||[]).find(d=>d.lang==='en')?.value,2).slice(0,300),(c.references||[])[0]?.url]}).sort((a,b)=>(b[2]||0)-(a[2]||0)).slice(0,15)}}catch(e){out.errors.push('nvd '+e.message)}
// 7. Nobel Prize API: this year's prizes (CC0)
try{const j=await (await fetch(`https://api.nobelprize.org/2.1/nobelPrizes?nobelPrizeYear=${today.getUTCFullYear()}`)).json();out.nobel=(j.nobelPrizes||[]).map(p=>[p.category?.en,p.dateAwarded,(p.laureates||[]).map(l=>(l.knownName||l.orgName)?.en).join(', '),clean((p.laureates||[])[0]?.motivation?.en),p.links?.[0]?.href])}catch(e){out.errors.push('nobel '+e.message)}

const clean=s=>(s||'').replace(/\s+/g,' ').trim();const strip=s=>(s||'').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();const firstSentences=(t,n)=>{const p=(t||'').replace(/\s+/g,' ').replace(/\b(U\.S|U\.K|E\.U|Dr|Mr|Mrs|Ms|St|No|vs|etc|Inc|Ltd|Co|Jr|Sr|Prof|Gen|Sen|Rep|Gov|e\.g|i\.e|approx|Fig|al)\.(?=\s)/g,m=>m.replace(/\./g,'\u0001')).replace(/(\S)\.(?=\S)/g,'$1\u0001');const m=p.match(/[^.!?]+[.!?]+(\s|$)/g)||[p];return m.slice(0,n).join('').replace(/\u0001/g,'.').trim()};
const out={cisa:{},errors:[]};
const rss=async(u,n,tag)=>{const b=await (await fetch(u)).arrayBuffer();const t=new TextDecoder('utf-8').decode(b);const d=new DOMParser().parseFromString(t,'text/xml');return [...d.querySelectorAll('item, entry')].slice(0,n).map(i=>{const dt=i.querySelector('pubDate, published, updated')?.textContent||'';const dd=new Date(dt);return [clean(i.querySelector('title')?.textContent),isNaN(dd)?dt.slice(0,10):dd.toISOString().slice(0,10),(i.querySelector('link')?.textContent||i.querySelector('link')?.getAttribute('href')||'').trim(),firstSentences(strip(i.querySelector('description, summary, content')?.textContent).replace(/^(View CSAF\s*)?(Summary\s*)?(Advisory at a Glance\s*)?/,'').replace(/^Title .*?Executive [Ss]ummary\s*/,''),2).slice(0,320),tag]})};
try{out.cisa.joint=await rss('https://www.cisa.gov/cybersecurity-advisories/cybersecurity-advisories.xml',10,'CISA cybersecurity advisory')}catch(e){out.errors.push('cisaJoint '+e.message)}
try{out.cisa.all=(await rss('https://www.cisa.gov/cybersecurity-advisories/all.xml',30,'CISA')).filter(x=>!/^CISA Adds .* Known Exploited/.test(x[0])&&!/ics-advisories/.test(x[2])).slice(0,12)}catch(e){out.errors.push('cisaAll '+e.message)}
try{out.cisa.ics=(await rss('https://www.cisa.gov/cybersecurity-advisories/ics-advisories.xml',30,'CISA ICS advisory')).slice(0,12)}catch(e){out.errors.push('cisaIcs '+e.message)}
try{out.cisa.news=await rss('https://www.cisa.gov/news.xml',8,'CISA news')}catch(e){out.errors.push('cisaNews '+e.message)}

const clean=s=>(s||'').replace(/\s+/g,' ').trim();const strip=s=>(s||'').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();const firstSentences=(t,n)=>{const p=(t||'').replace(/\s+/g,' ').replace(/\b(U\.S|U\.K|E\.U|Dr|Mr|Mrs|Ms|St|No|vs|etc|Inc|Ltd|Co|Jr|Sr|Prof|Gen|Sen|Rep|Gov|e\.g|i\.e|approx|Fig|al)\.(?=\s)/g,m=>m.replace(/\./g,'\u0001')).replace(/(\S)\.(?=\S)/g,'$1\u0001');const m=p.match(/[^.!?]+[.!?]+(\s|$)/g)||[p];return m.slice(0,n).join('').replace(/\u0001/g,'.').trim()};
const out={nih:[],errors:[]};
try{const b=await (await fetch('https://www.nih.gov/news-releases/feed.xml')).arrayBuffer();const t=new TextDecoder('utf-8').decode(b);const d=new DOMParser().parseFromString(t,'text/xml');out.nih=[...d.querySelectorAll('item')].slice(0,15).map(i=>{const dt=clean(i.querySelector('pubDate')?.textContent);const m=dt.match(/(\d{2})\/(\d{2})\/(\d{4})/);return [clean(i.querySelector('title')?.textContent),m?`${m[3]}-${m[1]}-${m[2]}`:dt.slice(0,10),clean(i.querySelector('link')?.textContent),firstSentences(strip(i.querySelector('description')?.textContent),2).slice(0,300),'NIH news release']})}catch(e){out.errors.push('nih '+e.message)}

const clean=s=>(s||'').replace(/\s+/g,' ').trim();const firstSentences=(t,n)=>{const p=(t||'').replace(/\s+/g,' ').replace(/\b(U\.S|U\.K|E\.U|Dr|Mr|Mrs|Ms|St|No|vs|etc|Inc|Ltd|Co|Jr|Sr|Prof|Gen|Sen|Rep|Gov|e\.g|i\.e|approx|Fig|al)\.(?=\s)/g,m=>m.replace(/\./g,'\u0001')).replace(/(\S)\.(?=\S)/g,'$1\u0001');const m=p.match(/[^.!?]+[.!?]+(\s|$)/g)||[p];return m.slice(0,n).join('').replace(/\u0001/g,'.').trim()};
const out={arxiv:{},errors:[]};
const q=async(cat,n)=>{const b=await (await fetch(`https://export.arxiv.org/api/query?search_query=${cat}&sortBy=submittedDate&sortOrder=descending&max_results=${n}`)).arrayBuffer();const t=new TextDecoder('utf-8').decode(b);const d=new DOMParser().parseFromString(t,'text/xml');return {total:+(d.getElementsByTagNameNS('http://a9.com/-/spec/opensearch/1.1/','totalResults')[0]?.textContent||0),items:[...d.querySelectorAll('entry')].map(e=>[clean(e.querySelector('title')?.textContent),(e.querySelector('published')?.textContent||'').slice(0,10),e.querySelector('id')?.textContent.trim(),firstSentences(clean(e.querySelector('summary')?.textContent),2).slice(0,320),[...e.querySelectorAll('author name')].slice(0,3).map(a=>clean(a.textContent)).join(', ')+(e.querySelectorAll('author').length>3?' et al.':''),[...e.querySelectorAll('category')].map(c=>c.getAttribute('term')).slice(0,3)])}};
try{out.arxiv.ai=await q('cat:cs.AI+OR+cat:cs.LG+OR+cat:cs.CL',12);await new Promise(r=>setTimeout(r,3500));out.arxiv.quant=await q('cat:quant-ph',6);await new Promise(r=>setTimeout(r,3500));out.arxiv.astro=await q('cat:astro-ph.EP+OR+cat:astro-ph.HE',6)}catch(e){out.errors.push('arxiv '+e.message)}

const clean=s=>(s||'').replace(/\s+/g,' ').trim();
const out={eurek:[],errors:[]};
try{for(const pg of ['','/2','/3']){const b=await (await fetch('https://www.eurekalert.org/news-releases/browse'+pg+'?view=summaries')).arrayBuffer();const t=new TextDecoder('utf-8').decode(b);const d=new DOMParser().parseFromString(t,'text/html');
 for(const p of d.querySelectorAll('article.post')){const a=p.querySelector('a[href*="/news-releases/"]');if(!a)continue;const dt=clean(p.querySelector('.reltime')?.textContent);const dd=new Date(dt);
  out.eurek.push([clean(p.querySelector('.post_title')?.textContent).slice(0,200),isNaN(dd)?dt:dd.toISOString().slice(0,10),'https://www.eurekalert.org'+a.getAttribute('href'),clean(p.querySelector('.intro')?.textContent).slice(0,320),clean(p.querySelector('.author')?.textContent).slice(0,90),clean(p.querySelector('.category')?.textContent).slice(0,60)])}}
 const seen=new Set();out.eurek=out.eurek.filter(x=>!seen.has(x[2])&&seen.add(x[2])).slice(0,30)}catch(e){out.errors.push('eurek '+e.message)}

